# File: config.py
# Purpose: Load application configuration from YAML files
# Project: coding-screen | Date: 2026-07-11
#
# Overview: Reads YAML configuration files and provides a dict-like
# interface for accessing settings. Currently supports basic YAML parsing
# and type conversion. Missing: environment variable override support.

import os
import yaml
from typing import Any, Dict, Optional


class Config:
    """Load and manage application configuration."""

    def __init__(self, config_path: str):
        """
        Initialize config loader with a YAML file path.

        Args:
            config_path: Path to YAML configuration file
        """
        self.config_path = config_path
        self.data: Dict[str, Any] = {}
        self._load()

    def _load(self) -> None:
        """Load configuration from YAML file."""
        if not os.path.exists(self.config_path):
            raise FileNotFoundError(f"Config file not found: {self.config_path}")

        with open(self.config_path, "r") as f:
            self.data = yaml.safe_load(f) or {}

        # Apply environment variable overrides
        self._apply_env_overrides()

    def _apply_env_overrides(self) -> None:
        """Apply environment variable overrides to configuration."""
        for key, value in self.data.items():
            if isinstance(value, dict):
                # Handle nested dictionaries
                for sub_key, sub_value in value.items():
                    env_key = f"APP_{key.upper()}_{sub_key.upper()}"
                    if env_key in os.environ:
                        self.data[key][sub_key] = self._convert_env_value(os.environ[env_key])
            else:
                # Handle top-level keys
                env_key = f"APP_{key.upper()}"
                if env_key in os.environ:
                    self.data[key] = self._convert_env_value(os.environ[env_key])

    def _convert_env_value(self, value: str) -> Any:
        """Convert environment variable string to appropriate type."""
        # Try to convert to boolean
        if value.lower() in ('true', 'false'):
            return value.lower() == 'true'

        # Try to convert to integer
        try:
            return int(value)
        except ValueError:
            pass

        # Try to convert to float
        try:
            return float(value)
        except ValueError:
            pass

        # Return as string if no conversion worked
        return value

    def get(self, key: str, default: Optional[Any] = None) -> Any:
        """
        Get a configuration value by dot-notation key.

        Args:
            key: Configuration key (e.g., "database.host")
            default: Default value if key is not found

        Returns:
            Configuration value or default
        """
        keys = key.split(".")
        value = self.data
        try:
            for k in keys:
                value = value[k]
            return value
        except (KeyError, TypeError):
            return default
EOF"}
